package com.intellilib.server.service;
import com.intellilib.server.model.ApiModels.NotificationView; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Service; import java.util.List;
@Service public class NotificationService { private final JdbcTemplate jdbc; private final SimpMessagingTemplate ws; public NotificationService(JdbcTemplate j,SimpMessagingTemplate w){jdbc=j;ws=w;} public void send(long userId,String title,String message){ jdbc.update("INSERT INTO notifications(user_id,title,message) VALUES(?,?,?)",userId,title,message); ws.convertAndSend("/topic/user/"+userId,java.util.Map.of("type","notification","title",title,"message",message)); } public List<NotificationView> list(long userId){ return jdbc.query("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50",(r,n)->new NotificationView(r.getLong("id"),r.getString("title"),r.getString("message"),r.getObject("created_at",java.time.OffsetDateTime.class),r.getObject("read_at")!=null),userId); } }
